package br.com.pelotavision;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import java.nio.file.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE,qualifiers="w400dp-h820dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class DetailedDemoTest {
 @Test public void rendersActualDetailOptionsAndSuppliedRoiResult()throws Exception{
  File dir=new File(System.getProperty("pelotavision.validationDir"),"detail-0.11.0");JSONObject input=new JSONObject(new String(Files.readAllBytes(new File(dir,"analysis.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));Bitmap photo=BitmapFactory.decodeFile(new File(dir.getParentFile(),"belt-0.9.0/input_correia.jpg").toString());assertNotNull(photo);List<PelletDetector.Detection> objects=new ArrayList<>();List<CrackAnalysis.Entry> entries=new ArrayList<>();JSONArray ds=input.getJSONArray("objects");
  for(int i=0;i<ds.length();i++){JSONObject d=ds.getJSONObject(i);PelletDetector.Detection seed=new PelletDetector.Detection(d.getDouble("crack_x"),d.getDouble("crack_y"),d.getDouble("crack_radius"),Math.PI*Math.pow(d.getDouble("crack_radius"),2),d.getDouble("roundness"),d.getBoolean("partial"),d.getBoolean("crack_review"));objects.add(new PelletDetector.Detection(seed,d.getDouble("x"),d.getDouble("y"),d.getDouble("a"),d.getDouble("b"),d.getDouble("angle"),d.getBoolean("fitted"),d.isNull("support")?Double.NaN:d.getDouble("support"),d.isNull("rms")?Double.NaN:d.getDouble("rms"),d.getBoolean("partial"),d.getBoolean("review")));JSONArray rs=d.getJSONArray("crack_runs");float[] runs=new float[rs.length()];for(int j=0;j<runs.length;j++)runs[j]=(float)rs.getDouble(j);entries.add(new CrackAnalysis.Entry(i+1,CrackAnalysis.Status.valueOf(d.getString("crack_status")),runs,d.isNull("crack_score")?Double.NaN:d.getDouble("crack_score"),"random_forest_20261018_v1"));}


  PelletDetector.Result all=new PelletDetector.Result(objects,photo.getWidth(),photo.getHeight(),objects.size(),input.getLong("duration_ms"),false,input.getString("method"));CrackAnalysis cracks=new CrackAnalysis(all.width,all.height,50,0,entries);InterestRegion roi=new InterestRegion(InterestRegion.Shape.RECTANGLE,440,340,860,940);DetailGeometry map=new DetailGeometry(420,600,all.width,all.height,1,1,440,340,1,roi);int[] treatmentCounts=new int[4];for(int i=0;i<4;i++)treatmentCounts[i]=input.getJSONArray("treatments").getInt(i);DetailedAnalysis.Report report=new DetailedAnalysis.Report(map,input.getInt("tiles"),input.getInt("baseline"),objects.size(),treatmentCounts,true,true,input.getLong("duration_ms"),"log_p1_s90",Collections.emptyList());
  try(var ctl=Robolectric.buildActivity(MainActivity.class).setup()){
   MainActivity a=ctl.get();ObjectCalibrationTest.setup(a);Bitmap dummy=(Bitmap)ObjectCalibrationTest.get(a,"photoBitmap");ObjectCalibrationTest.set(a,"photoBitmap",photo);dummy.recycle();ObjectCalibrationTest.set(a,"photoAllResult",all);ObjectCalibrationTest.set(a,"photoAllCracks",cracks);ObjectCalibrationTest.set(a,"originalWidth",all.width);ObjectCalibrationTest.set(a,"originalHeight",all.height);try(var stream=new FileInputStream(new File(dir.getParentFile().getParentFile(),"app/src/main/assets/crack_forest.pvrf"))){ObjectCalibrationTest.set(a,"crackModel",new CrackModel(stream));}ObjectCalibrationTest.set(a,"photoDetailReport",report);ObjectCalibrationTest.set(a,"detailMode",true);ObjectCalibrationTest.set(a,"detailSr",true);ObjectCalibrationTest.call(a,"applyRegion",new Class[]{InterestRegion.class},roi);((View)ObjectCalibrationTest.get(a,"frozen")).setVisibility(View.VISIBLE);ActiveRoiDemoTest.render(a,new File(dir,"Tela_ROI_detalhada.png"));
   ObjectCalibrationTest.call(a,"showSegmentationOptions",new Class[]{});android.app.AlertDialog d=ObjectCalibrationTest.dialog();renderDialog(d,new File(dir,"Tela_Opcoes_Detalhada.png"));assertTrue(((CheckBox)ObjectCalibrationTest.tag(d,"detail_sr")).isChecked());d.dismiss();ObjectCalibrationTest.call(a,"showDetailSummary",new Class[]{});d=ObjectCalibrationTest.dialog();renderDialog(d,new File(dir,"Tela_Comparacao_Detalhada.png"));d.dismiss();
   Bitmap composite=PhotoComposer.compose(photo,all,cracks,null,roi,0,true);BeltDemoTest.png(composite,new File(dir,"Relatorio_Detalhado.png"));composite.recycle();assertEquals(objects.size(),((PelletDetector.Result)ObjectCalibrationTest.get(a,"photoResult")).circles.size());assertEquals("Detalhada · ver comparação",((TextView)ObjectCalibrationTest.get(a,"profileLabel")).getText().toString());
  }
 }
 static void renderDialog(android.app.Dialog d,File path)throws Exception{View root=d.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1540,View.MeasureSpec.AT_MOST));root.layout(0,0,800,root.getMeasuredHeight());Bitmap b=Bitmap.createBitmap(800,root.getHeight(),Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));BeltDemoTest.png(b,path);b.recycle();}
}
